"""Render a separate forensic review without changing completed study artifacts."""
from __future__ import annotations
import html
from html.parser import HTMLParser
import json
from pathlib import Path
import hashlib
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

REPO = Path(__file__).resolve().parents[1]
OUT = REPO / 'data/backtests/analysis/olr_next_targeted_20261011'
OLD = OUT.parent / 'olr_opening_risk_20261010'

def read(p): return json.loads(p.read_text(encoding='utf-8'))
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    d = read(OUT/'diagnosis.json'); r = read(OLD/'results.json')
    assert read(OLD/'selected_research_policy.json')['results_sha256'] == sha(OLD/'results.json')
    for p, h in d['source_sha256'].items(): assert sha(Path(p)) == h, p
    assert sha(REPO/'scripts/olr_next_targeted_diagnosis_v3.py') == d['script_sha256']
    control = r['candidates'][0]
    blocks = []
    def p(s): blocks.append('<p>'+s+'</p>')
    def table(headers, rows):
        blocks.append('<div class="table"><table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>')
    def label(s): p('<strong>'+s+'</strong>')
    def link(path, label): return '<a href="'+Path(path).as_uri()+'">'+label+'</a>'

    p('<strong>OLR: why the latest round failed, and the next targeted experiments</strong><br>11 October 2026 · Read-only forensic review · IS 7 August 2025–31 March 2026; OOS-labelled development window 1 April–10 July 2026.')
    p('The completed round rejected three particular implementations. It did not establish that the strategy cannot improve. Its central weakness was a mismatch between the mechanisms tested and the mechanisms producing the remaining risk: a non-binding one-share opening-price estimator, an indiscriminate allocation cap, and an exit trigger that confused temporary weakness with persistent failure. None created additional OOS entry opportunities. The next round should address execution-horizon risk, distinguish structural failure from recoverable weakness, and test a small addition to already-qualified entry opportunities. The final portfolio must still clear the original preservation and audit gates.')
    p('This review adds authenticated signal-funnel reconstruction, marginal top-up accounting, exact matched-trade P&L decomposition, and one new structural-exit screen. It changes no strategy configuration and runs no new portfolio-return backtest. The new screens are diagnostic evidence, not qualified successor performance. The existing selected profile remains a comparator while these hypotheses are tested; retention is an interim operational decision, not a research endpoint.')
    label('What the completed native experiments actually established')
    rows=[]
    policies=[('Original',r['references']['original']),('Prior 1R guard',r['references']['guard']['windows'])]+[(c['label'],c['windows']) for c in r['candidates']]
    for name, win in policies:
        rows.append([name]+[f"{win[w][k]:.3f}" if k!='trades' else str(win[w][k]) for w in ['train','oos'] for k in ['return_pct','drawdown_pct','trades']])
    table(['Policy','IS return %','IS intraday DD %','IS trades','OOS return %','OOS intraday DD %','OOS trades'],rows)
    p('The selected policy had already improved OOS return from −3.328% to +12.190% and reduced intraday maximum drawdown from 29.162% to 16.281%, with IS return down 1.408 percentage points from the original. The remaining risk is substantial, but the earlier exit-priority repair and scenario sizing were economically effective. Reverting those verified repairs would discard useful progress.')
    p('The 55% cap gained only 0.172 OOS return points and reduced DD by 0.446 points, while costing 2.706 IS return points versus the current selection. The partial exit cost 5.320 IS return points and 1.070 OOS points, while reducing OOS DD by only 0.536 points. These are adverse trade-offs under the stated objective, not near misses caused solely by administrative gates. All three variants still made 46 OOS trades on 29 entry days.')
    p('The binding nominal IS return floor was 52.138595%: current selection minus 1.5pp. Original minus 3pp is 52.046591%, only 0.092004pp lower. Removing the current-selection guard would therefore not rescue either harmful variant. The OOS floors were return ≥12.439796% and DD ≤15.530715%. Keep those safeguards; improve experiment design rather than redefining success after failure.')

    label('1. The tail-risk experiment did not reach the risk it was supposed to control')
    p('Correction after implementation review: the estimator used prior official close to the next first capacity-eligible continuous opening price. This was 09:05 in the two fast-loss cases, so it already incorporated their first five-minute movement. Its loss unit was max(1.25 ATR, entry price × estimated adverse opening loss), plus modeled costs. Only 3/186 IS and 7/46 OOS admitted trades had an estimate above the ATR floor, and those orders were constrained elsewhere: native size in all three IS cases and six OOS cases, and gross exposure in the seventh OOS case. No executed quantity or equity path changed. This was an inactive economic intervention, not evidence that tail-aware sizing cannot help.')
    p('The remaining issue is the distinction between a one-share price proxy and a quantity-dependent entry-to-liquidation scenario. The 042660 and 403870 trades lost ₩9.122m combined. Their price bridges contain ₩2.356m of overnight-gap loss and ₩5.8585m during the first five-minute bar—64.2% of their total loss occurred in that first bar. Both had already crossed the 1R guard before the first eligible 09:05 fills. The old estimator did capture the 09:05 endpoint in these cases; my earlier claim that it omitted the first bar was incorrect. Its legitimate limitations are the previous-close reference, one-share feasibility, unconditional pooling and absence of binding quantity changes. Simply tightening a completed-bar stop cannot retrieve a price that was unavailable under the execution model.')
    p('A replacement estimator should measure adverse loss through a capacity-supported liquidation horizon: opening gap, opening interval, subsequent fills and costs. Historical labels may use completed later prices, but a decision on day t must use only labels whose full exit horizons ended before t. Use the same frozen quote, session, halt and corporate-action rules as the replay, and calculate quantity-specific liquidation rather than extrapolating one-share feasibility to the entire position. Keep the 4%/6%/8% position/sector/account allowances fixed initially, and compare predicted account loss with realized loss and actual binding quantities before spending another full qualification run.')
    p('For correlated holdings, replay aligned historical date shocks across the whole candidate basket. Summing independent single-name expected shortfalls or taking a mean peer gap can understate a common sector shock. Use shrinkage where sample support is weak and disclose uncertainty; do not increase quantiles until the estimator happens to clip the named historical losers. A useful model must discriminate risk before entry and preserve profitable exposure in IS. An activation check is necessary, but activation alone is not evidence of improvement.')

    label('2. Why the broad partial exit failed, and a more selective candidate')
    p('The tested trigger sold half after three completed bars in a later session when close ≤−0.4R and observed MFE &lt;0.5R. Low MFE and a temporary loss did not establish permanent failure. In matched trades, six IS winners and two OOS winners became non-positive. Across matched OOS trades, losses improved by ₩0.740m but winners deteriorated by ₩1.810m. Thus the mechanism did precisely what the user wanted to avoid: its cost to recovering winners exceeded its benefit to losers.')
    table(['Weak-partial P&L change versus selection, KRW m','IS','OOS'],[
        ['Per-unit execution effect','−1.368','−0.415'],['Quantity effect','−3.522','−0.655'],
        ['Added/removed entry-set effect','−0.431','0.000'],['Total','−5.320','−1.070']])
    p('This is an exact accounting identity, not a causal experiment: old quantity × change in net P&L per share, plus quantity change × new net P&L per share, plus added/removed trades. It shows that the failure was not just stop timing. Earlier realizations and altered cash paths changed subsequent position sizes. For example, IS 010130 on 23 January fell from 30 to 20 shares and lost approximately ₩2.137m of profit; other later losing trades became substantially larger. A useful exit must be qualified with its induced allocation and compounding effects, not only on isolated trade charts.')
    p('I tested one tighter diagnostic condition without searching a threshold grid: retain the existing weak-partial conditions, and require two contiguous completed closes below both the entry-session low and that session’s cumulative typical-price VWAP. The entry-session low is known before the later session starts; VWAP uses only completed bars. The screen is restricted to times before the incumbent native exit condition. It is a structural-failure hypothesis rather than another chosen R threshold.')
    table(['Observed-path trigger set','IS trades / eventual winners','OOS trades / eventual winners'],[
        ['Original weak-partial screen','59 / 9','14 / 3'],['With structural confirmation','21 / 0','5 / 0']])
    p('The five OOS cases are 011790 entered 28 April, 069960 on 29 April, 034730 on 11 May, 042700 on 14 May and 329180 on 27 May. The stronger condition first triggers at 09:45 on 28 May for 329180, ahead of its later full guard. It leaves the observed recovering winners outside the trigger set. It does not address the instantaneous opening losses in 042660 or 403870, and zero historical winner hits in this small inspected sample is not a guarantee of future preservation.')
    p('For a half exit, known one-bar capacity supports a simple next-open calculation for only 9 of the 21 IS cases and 3 of the 5 OOS cases. Those subsets improve isolated P&L by just ₩0.052m IS and ₩0.188m OOS. Three supported IS losers and one OOS loser become worse; even eventual losers can recover enough to make an earlier sale costly. The remaining cases are unresolved, not zero-effect. The large 034730 case lacks enough one-bar capacity for the proposed half sale. This is a better-separated hypothesis worthy of a native pilot, not evidence of a large DD reduction yet.')
    p('Keep the half fraction and existing guard precedence fixed in the pilot. Preserve one-shot lifecycle state, cancellation acknowledgement, remaining inventory reconciliation and pending-market-exit precedence. Record each actual exit leg and compare the old-quantity diagnostic with the full native cash account. Do not add re-entry or change thresholds in the same experiment; that would obscure whether the structural confirmation itself helped.')

    label('3. Why indiscriminate concentration reduction is an expensive repair')
    p('The 55% cap’s IS deterioration is largely quantity-driven: ₩−2.819m quantity effect, ₩−0.023m per-unit effect and ₩+0.136m from changed entry membership. It changed the amount invested in profitable opportunities without adding enough valuable replacements. OOS gain was only ₩0.172m. The rank-weighted allocator still needs better calibration, but the evidence rejects a blanket cap reduction as the immediate answer.')
    p('Rank 1 contributed ₩+37.620m IS and ₩−4.335m OOS under the selected policy; rank 2 contributed ₩+12.674m and ₩+11.753m respectively. This is consistent with rank not being a stable estimate of absolute expected payoff. It does not justify swapping ranks after seeing OOS. Similarly, the low-score band earned ₩+26.592m IS but lost ₩−5.819m OOS; deleting it would endanger substantial IS alpha. Use these observations to investigate conditional payoff and adverse-tail calibration, not to blacklist past losers or sectors.')
    p('Recycled top-ups are not the loss source here. Three IS trades received approved extras, only two had filled quantity above the base allocation; one OOS trade received filled extras. All of those filled-extra trades were profitable, and none of the four major OOS losers received a top-up. The base-first, same-price slice attributes ₩+3.848m IS and ₩+2.089m OOS to extra quantity. This is descriptive rather than a causal no-top-up replay, but it directly contradicts the hypothesis that removing the recycling overlay would target these losses.')
    p('The IS endpoint is unusually dependent on profitable regimes: account gains during January and February total about ₩48.35m, roughly 90% of the entire ₩53.64m IS gain; March adds no trades or profit. A global size cut removes the very convex upside that the IS preservation objective protects. More selective adverse-horizon sizing and incremental entry opportunities are preferable research directions. They still need full evidence before adoption.')

    label('4. The entry bottleneck is measurable; extra slots alone cannot fix it')
    table(['Funnel, candidate-days unless marked','IS','OOS'],[
        ['Entry snapshot dates',154,67],['Dates with no final candidates',54,32],
        ['Empty at daily selection',18,16],['Became empty at afternoon selection',36,16],
        ['Daily eligible pool before top-20 truncation',2118,674],['Daily overflow',436,96],
        ['Candidates reaching afternoon evaluation',1682,578],['Afternoon rejections',1315,504],
        ['Final top-eight candidates',356,74],['Within six slots',332,74],
        ['Native entered lifecycles',186,46],['Unique entry days',88,29]])
    p('IS afternoon evaluation admits 367 before top-eight truncation, which removes 11; OOS admits 74 and loses none there. Every OOS final candidate already fits within six slots. Increasing the slot count or changing exits cannot create candidates on the 32 empty OOS dates. Trades per entry-snapshot date fell from 1.208 to 0.687, while the first-six candidate supply fell from 2.156 to 1.104. Conditional conversion was actually higher OOS: 46/74 versus 186/332. The dominant frequency deterioration is thinner opportunity supply, not simply fewer available slots.')
    p('OOS afternoon rejections include 376 with negative afternoon return, 255 with negative lagged sector flow and 221 with negative lagged stock flow; reasons overlap. The two negative-return labels describe the same 376 cases and must not be summed. Only 11 were rejected at the score-band stage. Thirty-six have lagged sector flow as their sole recorded afternoon reason and twenty have lagged stock flow alone. A sole recorded reason is stage-local: later score-band gates may not have been evaluated, so these are upper bounds on candidates a gate repair could recover, not proven extra entries.')
    p('The daily sector-participation floor is 0.5. It appears in 5,127 OOS rejection records and is the sole recorded daily reason in 2,285. The 20-day return boundary rejects 565 OOS candidate-days compared with 161 IS, despite the shorter OOS period. These counts describe a regime-sensitive supply restriction. Removing these gates indiscriminately could force trades into weak markets and recreate the drawdown problem. Missing-data, broken-trend and liquidity requirements should not be relaxed to manufacture activity.')
    p('I reconstructed the frozen native entry signal for every candidate within six slots and matched the decision timestamp of all 186 IS and 46 OOS actual trades. Of the 28 OOS non-entries, 21 never pass the six-bar confirmation and seven have a valid signal but no submitted buy. Three of those seven already hold the same symbol at that time, which is consistent with intended duplicate-position protection. The other four need explicit core-allocation rejection tracing; the saved admissions file is empty. It would be unsupported to label all seven as lost profitable trades or as recoverable funding failures.')
    p('A single bounded timing screen—nine bars instead of six, leaving all price/VWAP/close-location conditions unchanged—finds 12 additional IS signals and three OOS signals. OOS examples are 032640 on 13 April at 15:05, 112610 on 22 April at 15:10 and 000660 on 7 May at 15:10, using source bar labels. The signal only becomes usable after its completed bar. This suggests a late-confirmation sleeve through the final supported continuous-entry interval, funded only by actual residual cash and remaining risk/capacity; it must preserve earlier incumbent admissions. No return or successful fill is claimed for these signals. A late order has less time to fill, which is material under the 0.5% participation stress.')
    p('If that small sleeve proves too sparse, the next opportunity-source investigation should be one narrowly defined stale-sector-flow exception: an otherwise valid candidate with positive stock flow and current intraday sector confirmation, rejected solely at the lagged-sector-flow stage. Restore all later score and entry gates before counting it. Evaluate that condition chronologically in IS, including real exit horizons, and fund it only from genuine residual resources. Do not simultaneously open the score-band gaps, lower sector participation and remove the stock-flow filter; that would become a broad alpha search.')

    label('5. Improve the experiment design while preserving final acceptance criteria')
    p('The previous combination rule required two mechanisms to qualify individually before their combination could be tested. That is conservative but unsuitable for a complementary package: risk reduction may temporarily sacrifice return, while an extra-opportunity mechanism may raise return and frequency without reducing DD on its own. Requiring every component to solve every objective can exclude a useful interaction without ever measuring it. The correction is to preregister a small interaction test, not relax the final portfolio gates.')
    table(['Order','Targeted work','Decision it resolves'],[
        ['A','Execution-horizon tail model + binding/capacity audit','Can risk sizing act before the opening interval, selectively?'],
        ['B','Native structurally confirmed half exit','Does improved winner separation survive actual fills and reinvestment?'],
        ['C','Residual-cash late confirmation, six → nine bars','Do already-approved late signals add profitable, genuine entries?'],
        ['D','One preregistered risk-plus-frequency combination','Can complementary effects clear the unchanged portfolio gates?']])
    p('Before A changes quantities, audit its lagged labels, historical support, calibration, risk-unit ratios and proposed reductions by IS winner/loser, rank, sector and date. If it remains non-binding, record that as a failed implementation of the hypothesis rather than a performance test. For B, report per-leg execution plus native account outcomes, and verify that its benefit is not merely a smaller intraday peak. For C, record rejected, proposed, funded, filled and expired opportunities separately. For D, identify the exact pair before viewing its combination result and run only that interaction. A component can fail a full-package improvement gate and still inform the predeclared interaction; the combination itself must pass every adoption gate.')
    p('Do not yet launch a generic 0.4/0.6/0.8R grid, reduce all position budgets, cap compounding globally, remove profitable top-ups, blacklist shipbuilders, or redefine DD as daily-close DD. The prior generic trail screen hurt IS winners. The selected daily-close DD is 10.940%, but the economically relevant intraday figure is 16.281%; changing the reporting frequency would hide exposure rather than repair it.')
    p('Final nominal gates should retain IS return ≥52.138595%, the original and guard return checks, IS DD ≤10.174960%, OOS return ≥12.439796% and OOS intraday DD ≤15.530715%. For the user’s frequency objective, strengthen the former 180/45 floors: preserve at least 186 IS and 46 OOS unique entry lifecycles and require an actual OOS increase, with entry days and funded notional disclosed. A split exit, repeated order, token-sized fill or extra inactive slot is not frequency improvement. Prefer packages that improve both returns and economically meaningful activity; never rank only on return/DD if doing so hides a frequency decline.')
    p('Repeat matched combined execution stress, retain all source/capacity/ledger audits, and use candidate/scenario-specific actual IS terminal histories. Stress must still preserve original/guard/selected IS thresholds and improve OOS risk without losing the stressed control’s return. Report both compounded and no-upward-compounding comparisons. The selected capped case gains about 0.994 OOS return points and reduces DD by 2.365 points, but costs 6.973 IS points; this rejects a blanket compounding cap under the current objective. A new package must earn its improvement through better trade handling and opportunities, not hide the IS cost by changing exposure accounting.')

    label('6. The attainable DD reduction must be assessed honestly')
    p('The selected peak-to-trough fall is ₩21.458m. Four losing trades explain 66.79%; three trades that still finish as winners explain 27.29% through profit giveback. The two fast opening losers alone explain 42.5%. A selective slow-failure exit can address only part of this episode. Opening risk needs pre-entry/pre-close exposure control or genuinely better execution evidence. Winner giveback needs a separate conditional payoff analysis; an indiscriminate profit trail has already shown an IS cost.')
    p('At the original fixed peak and trough, reaching 12% DD requires approximately ₩5.642m of improvement at the trough; 10% requires ₩8.278m. Those are scale checks, not counterfactual forecasts: new trades and exits move both endpoints. The supported structural-exit arithmetic is far smaller. It would therefore be misleading to promise that the new partial-exit condition alone can bring DD to 10–12%. A substantial reduction probably requires improvements across opening exposure, persistent failure and opportunity diversification.')
    p('Inspect the whole equity path: absolute and percentage peak-to-trough loss, drawdown duration, endpoint wealth, expected shortfall by entry cohort, return per unit of capital, worst session/sector, and the contribution of the largest winners. Use paired date blocks for uncertainty because trades entered together are dependent. Leave-one-large-event-out results are fragility diagnostics only; do not use them to remove inconvenient events from acceptance. Realized maximum DD is not a guaranteed future bound, and higher turnover is useful only when incremental net expectancy survives costs.')

    label('7. Warm-up, data validity and uncertainty remain separate obligations')
    p('The Aug 7 IS start comes from the inherited 60-session model-training window plus a one-session embargo, not absence of all older raw market data. Older completed intraday history feeds lagged features. The present OOS runs restore the matching candidate/scenario IS terminal liquidity state before April 1; tail-enabled runs also restore the actual IS tail state and check it against the independent OOS prefix. OOS has 217 prior market sessions, comprising 61 before IS scoring plus the 156-session IS interval. Resetting account equity to ₩100m does not imply resetting market history.')
    p('The earlier isolated boundary repair changed original OOS return only from −3.328% to −3.544% and DD from 29.162% to 29.174%. It did not explain the large underperformance. However, literal continuity is not the same as complete observation coverage. Auction-liquidity history remains dependent on the legacy shared symbol feed; 96/186 IS and 21/46 OOS trades enter with insufficient auction history. The first OOS entry has only one prior auction sample. Native realized capacity checks still apply, but the forecast may be uninformative when sparse.')
    p('The retained scoring also uses a legacy current-afternoon sector-volume feature that resolves to 1.0. The causal continuous panel changes score values and, on a few IS dates, membership/rank; its earlier uncalibrated substitution hurt IS. Treat a feature correction and its score calibration as a separate, explicitly versioned data-model migration. Keeping the same raw score bands after changing a feature distribution is not an adequate calibration test. Do not mix that migration into the immediate exit pilot, and do not describe the legacy feature as economically correct merely because it preserves old performance.')
    p('Sparse auctions, a fixed 103-name universe, non-point-in-time sector taxonomy, opening-price proxies and lack of a later source-qualified validation archive all limit inference. April–July has been inspected repeatedly and is development evidence. Freeze the next bounded study, use chronological IS diagnostics to avoid selecting on named OOS events, and obtain untouched later data or a precommitted forward shadow period for independent validation. '+link(Path(OLD/'report.html'),'The completed native study')+' supplies the comparator evidence; this document narrows the next hypotheses rather than asserting a new expected-return estimate.')
    p('The external methodological evidence is consistent with this approach: stop-loss policies can add or subtract value depending on the process they are applied to (<a href="https://dspace.mit.edu/entities/publication/bb69ca4b-0cdc-487f-831d-63b2e84fafee">Kaminski and Lo</a>), and repeated selection over the same backtest data raises false-discovery risk (<a href="https://www.davidhbailey.com/dhbpapers/backtest-prob.pdf">Bailey et al.</a>). Neither paper validates this OLR policy; the conclusions above come from its own frozen native evidence.')
    label('Reproducibility and deliverables')
    p('The forensic script reauthenticates six consumed native cases and their execution-audit receipts, checks the selected profile/result binding, reconciles the P&L decompositions, and reconstructs every actual entry signal timestamp. Sources and script hashes are recorded in diagnosis.json. No prior result collector was rerun, no source generation was edited, and no live policy was activated. The new three-bar/structural and nine-bar timing screens do not have native counterfactual portfolio results yet.')
    p('Files: '+link(OUT/'diagnosis.json','new diagnostic evidence')+' · '+link(REPO/'scripts/olr_next_targeted_diagnosis_v3.py','reproducible diagnostic script')+' · '+link(OLD/'report.html','completed native report')+' · '+link(OLD/'selected_research_policy.json','current selected research profile')+' · '+link(OLD/'review_bundle/implementation.patch','prior implementation patch')+'.')

    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10})
    fig, axes=plt.subplots(1,2,figsize=(13,5.3),gridspec_kw={'width_ratios':[1,1.2]})
    vals=[2.356,5.8585,9.12231405096-2.356-5.8585]
    names=['Overnight gap','First 5-minute bar','Other moves + fees']
    cols=['#64748b','#dc6546','#cbd5e1']
    axes[0].barh(names,vals,color=cols)
    for i,x in enumerate(vals):axes[0].text(x+.07,i,f'{x:.3f}',va='center')
    axes[0].set_xlim(0,7);axes[0].invert_yaxis();axes[0].set_xlabel('Loss contribution, KRW million')
    axes[0].set_title('Two fast opening losses\n042660 and 403870; total KRW 9.122m',loc='left',pad=15)
    names=['IS original trigger','IS structural trigger','OOS original trigger','OOS structural trigger']
    loses=[50,21,11,5];wins=[9,0,3,0]
    axes[1].barh(names,loses,color='#64748b',label='Eventually losing')
    axes[1].barh(names,wins,left=loses,color='#dc6546',label='Eventually profitable')
    for i,(a,b) in enumerate(zip(loses,wins)):axes[1].text(a+b+.8,i,f'{a+b} / {b} winners',va='center',fontsize=9)
    axes[1].set_xlim(0,80);axes[1].invert_yaxis();axes[1].set_xlabel('Observed trades affected before the native exit condition')
    axes[1].set_title('Stricter confirmation improves observed separation\nNo portfolio-return or drawdown claim',loc='left',pad=15)
    axes[1].legend(loc='lower right',frameon=False,fontsize=9)
    for a in axes:
        a.spines[['top','right']].set_visible(False);a.grid(axis='x',alpha=.15);a.set_axisbelow(True)
    fig.suptitle('OLR: target the correct loss interval and distinguish persistent failure',fontsize=15,x=.03,ha='left')
    fig.tight_layout(rect=(0,0.05,1,.9));fig.text(.03,.02,'Descriptive frozen-path accounting. Future outcomes are not known at the trigger. No new policy has qualified.',fontsize=9,color='#475569')
    fig.savefig(OUT/'diagnosis.png',dpi=170,bbox_inches='tight');plt.close(fig)
    blocks.insert(2,'<figure><img src="diagnosis.png" alt="Opening-loss decomposition and structural-exit screen counts"><figcaption>Frozen-path diagnostics; screen counts do not measure avoidable loss.</figcaption></figure>')
    body='\n'.join(blocks)
    doc='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OLR next targeted study: forensic review</title><style>body{max-width:1080px;margin:40px auto;padding:0 24px;font:17px/1.65 system-ui,sans-serif;color:#172536;background:#fbfcfe}p{margin:1.15em 0}strong{color:#0d314e}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px 11px;border-bottom:1px solid #d7dee7;text-align:left}th{background:#e9eff5}td:not(:first-child){font-variant-numeric:tabular-nums}.table{overflow-x:auto;margin:22px 0}img{max-width:100%;height:auto}figure{margin:25px 0}figcaption{font-size:13px;color:#526276}a{color:#1263a3}body>p:first-child{font-size:21px}</style><body>'+body+'</body></html>'
    (OUT/'report.html').write_text(doc,encoding='utf-8')
    class Plain(HTMLParser):
        def __init__(self):super().__init__();self.parts=[]
        def handle_data(self,data):self.parts.append(data)
        def handle_endtag(self,tag):
            if tag in ('p','tr','figcaption'):self.parts.append('\n\n')
            elif tag in ('th','td'):self.parts.append(' | ')
    parser=Plain();parser.feed(body)
    (OUT/'report.txt').write_text(''.join(parser.parts),encoding='utf-8')
    receipt={'diagnosis_sha256':sha(OUT/'diagnosis.json'),'report_html_sha256':sha(OUT/'report.html'),
             'report_text_sha256':sha(OUT/'report.txt'),'chart_sha256':sha(OUT/'diagnosis.png'),
             'report_script_sha256':sha(Path(__file__)),'source_hashes_rechecked':True,
             'prior_profile_result_binding_preserved':True,'new_native_policy_results':False}
    (OUT/'report_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'report':str(OUT/'report.html'),'words':len(''.join(parser.parts).split()),'checks':receipt},indent=2))

if __name__=='__main__':main()
